use std::sync::Mutex;

use backend::{
    Asset, Backend, BackendError, ComposeRequest, DescribeRequest, DragPrepareRequest,
    ImportResult, PreparedDrag,
};
use compose::{ComposeAction, ComposeFlow, ComposeSnapshot, dispatch};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

#[derive(Debug, Clone, PartialEq, Deserialize, Serialize)]
struct RecordedCall {
    method: String,
    args: Value,
}

/// Test double over the real `Backend` trait. Scripted replies are consumed in
/// call order; `(method, JSON arguments)` are logged in order.
struct RecordingBackend {
    responses: Mutex<Vec<Value>>,
    calls: Mutex<Vec<RecordedCall>>,
}

impl RecordingBackend {
    fn new(responses: Vec<Value>) -> Self {
        Self {
            responses: Mutex::new(responses),
            calls: Mutex::new(Vec::new()),
        }
    }

    fn record(&self, method: &str, args: Value) -> Result<Value, String> {
        self.calls.lock().expect("call log").push(RecordedCall {
            method: method.to_string(),
            args,
        });
        let response = self.responses.lock().expect("responses").remove(0);
        match response.get("__error__").and_then(Value::as_str) {
            Some(message) => Err(message.to_string()),
            None => Ok(response),
        }
    }

    fn take_calls(&self) -> Vec<RecordedCall> {
        std::mem::take(&mut self.calls.lock().expect("call log"))
    }
}

impl Backend for RecordingBackend {
    fn list_assets(&self) -> Result<Vec<Asset>, BackendError> {
        let value = self
            .record("assets_list", json!({}))
            .map_err(BackendError::validation)?;
        Ok(serde_json::from_value(value).unwrap_or_default())
    }
    fn import_paths(&self, paths: &[String]) -> Result<Vec<ImportResult>, BackendError> {
        let value = self
            .record("assets_import", json!({ "request": { "paths": paths } }))
            .map_err(BackendError::validation)?;
        Ok(serde_json::from_value(value).unwrap_or_default())
    }
    fn import_clipboard(
        &self,
        file_name: Option<&str>,
        bytes: &[u8],
    ) -> Result<Vec<ImportResult>, BackendError> {
        let value = self
            .record(
                "assets_import_clipboard",
                json!({ "request": { "fileName": file_name, "bytes": bytes } }),
            )
            .map_err(BackendError::validation)?;
        Ok(serde_json::from_value(value).unwrap_or_default())
    }
    fn run_describe(&self, request: DescribeRequest) -> Result<Vec<String>, BackendError> {
        let value = self
            .record(
                "pipeline_describe",
                json!({ "request": { "assetIds": request.asset_ids, "fields": request.fields } }),
            )
            .map_err(BackendError::validation)?;
        Ok(serde_json::from_value(value).unwrap_or_default())
    }
    fn run_compose(
        &self,
        request: ComposeRequest,
    ) -> Result<Vec<backend::Generation>, BackendError> {
        let value = self
            .record("pipeline_compose", json!({ "request": request }))
            .map_err(BackendError::validation)?;
        Ok(serde_json::from_value(value).unwrap_or_default())
    }
    fn cancel(&self) -> Result<(), BackendError> {
        self.record("pipeline_cancel", json!({}))
            .map_err(BackendError::validation)?;
        Ok(())
    }
    fn prepare_drag(&self, request: DragPrepareRequest) -> Result<PreparedDrag, BackendError> {
        let value = self
            .record(
                "drag_prepare",
                json!({ "request": { "assetId": request.asset_id, "payload": request.payload } }),
            )
            .map_err(BackendError::validation)?;
        Ok(
            serde_json::from_value(value).unwrap_or_else(|_| PreparedDrag {
                files: Vec::new(),
                prepared_dir: String::new(),
                suggested_name: String::new(),
            }),
        )
    }

    fn call(&self, command: &str, args: Value) -> Result<Value, BackendError> {
        self.record(command, args).map_err(BackendError::validation)
    }
}

#[derive(Debug, Deserialize)]
struct Step {
    action: ComposeAction,
    calls: Vec<RecordedCall>,
    responses: Vec<Value>,
    state: ComposeSnapshot,
}

#[derive(Debug, Deserialize)]
struct Scenario {
    name: String,
    steps: Vec<Step>,
}

#[derive(Debug, Deserialize)]
struct Corpus {
    scenarios: Vec<Scenario>,
}

#[test]
fn compose_panel_matches_recorded_typescript_behaviour() {
    let corpus: Corpus = serde_json::from_str(include_str!("../../port/corpus/compose.json"))
        .expect("parse compose corpus");
    let mut compared = 0usize;
    let mut differences: Vec<String> = Vec::new();

    for scenario in &corpus.scenarios {
        let mut flow = ComposeFlow::default();
        for (index, step) in scenario.steps.iter().enumerate() {
            let backend = RecordingBackend::new(step.responses.clone());
            dispatch(&mut flow, step.action.clone(), &mut |method, args| {
                backend
                    .call(method, args)
                    .map_err(|error| error.user_message)
            });
            let actual_calls = backend.take_calls();
            let actual_state = flow.snapshot();
            compared += 1;
            if actual_calls != step.calls || actual_state != step.state {
                differences.push(format!(
                    "{} / step {index} ({:?}):\n  expected calls {}\n  actual calls   {}\n  expected state {}\n  actual state   {}",
                    scenario.name,
                    step.action,
                    serde_json::to_string(&step.calls).unwrap_or_default(),
                    serde_json::to_string(&actual_calls).unwrap_or_default(),
                    serde_json::to_string(&step.state).unwrap_or_default(),
                    serde_json::to_string(&actual_state).unwrap_or_default(),
                ));
            }
        }
    }

    assert!(
        differences.is_empty(),
        "compose: {compared} inputs compared, {} differences\n{differences:#?}",
        differences.len()
    );
    println!(
        "compose: {compared} inputs compared, {} differences",
        differences.len()
    );
}
